import{z as s,x as n,o as e,c as D,q as t,j as r,D as a,d as A,s as i,S as o,b as B}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"异构并行","description":"","frontmatter":{"title":"异构并行","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/dist-heterogeneous-parallel.md","filePath":"llm/dist-heterogeneous-parallel.md","lastUpdated":1791063341000}'),d={name:"llm/dist-heterogeneous-parallel.md"};function p(h,E,m,P,C,f){const l=n("Mermaid");return e(),D("div",null,[E[2]||(E[2]=t('<h1 id="异构并行" tabindex="-1">异构并行 <a class="header-anchor" href="#异构并行" aria-label="Permalink to &quot;异构并行&quot;">​</a></h1><div class="epigraph"><p>同质集群里的「每卡」是近似，异构集群里它连近似都不是；并行方案要按设备的能力分账，而不是按台数平分。</p><footer>—— 据 Rajbhandari 等 2021 与 Zheng 等 2022 整理</footer></div><p><a href="/llm/dist-topology-aware">上一课</a>把逻辑组映射到同质的物理网格；真实集群常常不同质：两代卡混布、互连带宽不同、显存容量悬殊，CPU 与 NVMe 也作为存储与计算层参与训练。本课写异构下的并行：能力不齐时，切分与放置按什么配比走。不重讲 offload 的存储层级本身。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>均匀切分在异构集群退化为「最慢设备定义 step time」：同步语义下，每一步都要等最慢的参与者，快卡算得再快也只是空转。异构有三个来源，各自破坏不同的假设——算力差（同槽位插两代卡）破坏「每步等长时间」的假设；互连差（有的节点只有 PCIe）破坏「TP 住 NVLink 域」的放置前提；容量差（同集群 80GB 与 40GB 混布）破坏「每卡放同一份分片」的均匀切分前提。三类错法对应三处：按台数均匀切 DP 让快卡陪跑，把层内高频通信放到弱互连节点，按最大显存给每卡配分片让小卡必爆。</p><p><span class="marginnote">同步语义可以想象成划桨船：船速由最慢的桨手决定，其他人划得再快也只是空行程。这就是「按台数每卡一份」在异构集群失效的根源——计时的不是平均速度，是最慢的那张卡。</span></p><h3 id="按能力分账" tabindex="-1">按能力分账 <a class="header-anchor" href="#按能力分账" aria-label="Permalink to &quot;按能力分账&quot;">​</a></h3><p>补偿的第一手是按能力配比切分。PP 按各阶段的 FLOPs 配比分层：慢卡所在的阶段分到更少的层，使各阶段的计算时间对齐；DP 按容量与算力配 microbatch 或梯度累积步数——全局 batch 不变，各副本按自己的消化能力上量，步末归约时大家同时到齐。第二手是按亲和放置：计算通信比高的工作（大 GEMM 密集的阶段）放在弱互连但算力尚可的设备，通信密集的工作绝不放。第三手是把存储层级当成异构的一部分：优化器状态放 CPU、参数放 NVMe，本质是把「内存容量」也纳入分账，ZeRO 系列的卸载口径就是这套账的特例。</p><p><span class="marginnote">拿 DP 配比代个例子：快卡算力是慢卡的 2 倍，就让快副本每个外层步吃 2 个 microbatch、慢副本吃 1 个。全局 batch 不变，两个副本步内耗时一样长，步末归约同时到齐——快卡的算力真正进了吞吐，而不是烧在空转上。</span></p><p><span class="marginnote">Alpa 的做法把这件事交给搜索：intra-op 切分与 inter-op 调度在异构设备图上联合优化，代价是搜索本身要时间与算力预算。手写配比在两三种设备时够用，设备种类一多，手写组合数就压过了搜索成本。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>落地次序：先量账——每类设备的算力、显存、互连带宽实测，不抄规格表；再选轴——异构度主要打在哪条轴上（算力差先动 PP 配比，容量差先动 DP 配比与卸载，互连差先动放置）；最后定合同——慢设备要么按配比进入同步组并对齐时间，要么整体退出同步组另立作业，没有中间态。特别是一张「慢副本」混进同步 DP 组的方案要警惕：它每步都把全组按到自己的 step time，名义上多了算力，实际上少了吞吐。</p>',12)),(e(),r(o,null,{default:a(()=>[i(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20MEASURE%5B%22%E5%AE%9E%E6%B5%8B%E5%90%84%E8%AE%BE%E5%A4%87%3A%20%E7%AE%97%E5%8A%9B%20%2F%20%E6%98%BE%E5%AD%98%20%2F%20%E4%BA%92%E8%BF%9E%22%5D%20--%3E%20AXIS%7B%22%E5%BC%82%E6%9E%84%E5%BA%A6%E6%89%93%E5%9C%A8%E5%93%AA%E6%9D%A1%E8%BD%B4%3F%22%7D%0A%20%20AXIS%20--%3E%7C%E7%AE%97%E5%8A%9B%E5%B7%AE%7C%20PPX%5B%22PP%20%E6%8C%89%E9%98%B6%E6%AE%B5%20FLOPs%20%E9%85%8D%E6%AF%94%E5%88%86%E5%B1%82%22%5D%0A%20%20AXIS%20--%3E%7C%E5%AE%B9%E9%87%8F%E5%B7%AE%7C%20DPX%5B%22DP%20%E9%85%8D%E6%AF%94%20microbatch%20%2B%20%E5%8D%B8%E8%BD%BD%E5%88%86%E8%B4%A6%22%5D%0A%20%20AXIS%20--%3E%7C%E4%BA%92%E8%BF%9E%E5%B7%AE%7C%20AFF%5B%22%E9%80%9A%E4%BF%A1%E5%AF%86%E9%9B%86%E5%B7%A5%E4%BD%9C%E8%BF%9C%E7%A6%BB%E5%BC%B1%E4%BA%92%E8%BF%9E%E8%8A%82%E7%82%B9%22%5D%0A%20%20PPX%20--%3E%20ALIGN%5B%22%E5%90%84%E5%89%AF%E6%9C%AC%E5%AF%B9%E9%BD%90%20step%20%E6%97%B6%E9%97%B4%22%5D%0A%20%20DPX%20--%3E%20ALIGN%0A%20%20AFF%20--%3E%20ALIGN%0A%20%20ALIGN%20--%3E%20OUT%7B%22%E5%AF%B9%E4%B8%8D%E9%BD%90%3F%22%7D%0A%20%20OUT%20--%3E%7C%E6%98%AF%7C%20EXIT%5B%22%E6%85%A2%E8%AE%BE%E5%A4%87%E9%80%80%E5%87%BA%E5%90%8C%E6%AD%A5%E7%BB%84%2C%20%E5%8F%A6%E7%AB%8B%E4%BD%9C%E4%B8%9A%22%5D%0A%20%20OUT%20--%3E%7C%E5%90%A6%7C%20RUN%5B%22%E5%9B%BA%E5%AE%9A%E9%85%8D%E6%AF%94%E8%BF%9B%E8%AE%AD%E7%BB%83%E9%85%8D%E7%BD%AE%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B("h2",{id:"机制",tabindex:"-1"},[A("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=B("p",null,"同步语义下 step time 等于各副本时间的 max，配比的作用是把 max 拉平：配比正确的标准是各副本的步内时间差落在噪声带内，而不是「大致均衡」。数值一致性是异构特有的第二层账：不同代卡的 kernel 实现与精度路径不保证逐位一致，混合集群里的对拍要按设备分层做，把「卡型差异」与「并行差异」分开归因，否则调 debugging 时两个变量一起动。弹性与异构叠加时账更碎：新加入的设备与现存配比不齐，要么重配比，要么按上一课的口径在重放置时重验映射。",-1)),(e(),r(o,null,{default:a(()=>[i(l,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20UNI%5B%22%E6%8C%89%E5%8F%B0%E6%95%B0%E5%9D%87%E5%8C%80%E5%88%87%22%5D%0A%20%20%20%20U1%5B%22%E5%BF%AB%E5%8D%A1%3A%201%20%E4%BB%BD%2C%20%E7%AE%97%204%20%E7%A7%92%22%5D%20--%3E%20UW%5B%22%E6%AD%A5%E6%9C%AB%E7%AD%89%E6%85%A2%E5%8D%A1%22%5D%0A%20%20%20%20U2%5B%22%E6%85%A2%E5%8D%A1%3A%201%20%E4%BB%BD%2C%20%E7%AE%97%208%20%E7%A7%92%22%5D%20--%3E%20UW%0A%20%20%20%20UW%20--%3E%20US%5B%22step%20time%208%20%E7%A7%92%2C%20%E5%BF%AB%E5%8D%A1%E7%A9%BA%E8%BD%AC%E4%B8%80%E5%8D%8A%22%5D%0A%20%20end%0A%20%20subgraph%20PROP%5B%22%E6%8C%89%E8%83%BD%E5%8A%9B%E9%85%8D%E6%AF%94%E5%88%87%22%5D%0A%20%20%20%20P1%5B%22%E5%BF%AB%E5%8D%A1%3A%202%20%E4%BB%BD%2C%20%E7%AE%97%208%20%E7%A7%92%22%5D%20--%3E%20AL%5B%22%E6%AD%A5%E6%9C%AB%E5%90%8C%E6%97%B6%E5%88%B0%E9%BD%90%22%5D%0A%20%20%20%20P2%5B%22%E6%85%A2%E5%8D%A1%3A%201%20%E4%BB%BD%2C%20%E7%AE%97%208%20%E7%A7%92%22%5D%20--%3E%20AL%0A%20%20%20%20AL%20--%3E%20PS%5B%22step%20time%208%20%E7%A7%92%2C%20%E6%97%A0%E5%8D%A1%E7%A9%BA%E8%BD%AC%22%5D%0A%20%20end%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=t('<p><span class="marginnote">混合集群对拍时，初学者常把两代卡跑出的微小 loss 差直接当 bug 报；实际不同代卡的 kernel 与精度路径本就不保证逐位一致。先按设备分层对拍，把「卡型差」和「并行差」分开，再下结论。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 offload 的内部分级与瓦片调度（<a href="/llm/zero-offload">ZeRO-Offload</a>、<a href="/llm/zero-infinity">ZeRO-Infinity</a> 已给），不写推理侧的异构服务；MIG 一类切片管理是运维课题。能换卡时先换卡：异构补偿是「不能换」时的次优解，配比、放置、对拍的持续维护成本不低。搜索类方案（Alpa 一类）的搜索成本要计入项目预算，小集群手写更便宜。跨设备类型的数值差异在本课只作归因规则，数值协议本身归低精度与数值课程。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>异构三来源：算力差、互连差、容量差；各自破坏一个均匀切分的前提。</li><li>补偿三手：按能力配比切 PP 与 DP、按亲和放置、把存储层级计入分账。</li><li>同步组内没有中间态：按配比对齐时间，或整体退出同步组；慢副本陪跑是负收益。</li><li>对拍按设备分层归因，把卡型差异与并行差异分开。</li><li>出处：Rajbhandari 等，ZeRO-Infinity，2021 的存储分账；Zheng 等，Alpa，2022 的异构联合切分。</li></ul>',5))])}const F=s(d,[["render",p]]);export{u as __pageData,F as default};
